import{_ as a,o as r,c as t,a2 as i}from"./chunks/framework.BjkiRu3Q.js";const m=JSON.parse('{"title":"Backup, recovery & business continuity","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/backup-recovery.md","filePath":"getting-started/backup-recovery.md"}'),n={name:"getting-started/backup-recovery.md"};function o(s,e,c,d,l,u){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="backup-recovery-business-continuity" tabindex="-1">Backup, recovery &amp; business continuity <a class="header-anchor" href="#backup-recovery-business-continuity" aria-label="Permalink to &quot;Backup, recovery &amp; business continuity&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release</p><p>Operational guidance reviewed against v0.7.26. Verify the installed release, permissions and approved scope. Training uses authorized synthetic data; this guide does not authorize commercial activation.</p></div><h2 id="agree-a-recovery-plan" tabindex="-1">Agree a recovery plan <a class="header-anchor" href="#agree-a-recovery-plan" aria-label="Permalink to &quot;Agree a recovery plan&quot;">​</a></h2><p>The hosting and business owners must agree recovery point and recovery time objectives, retention, encryption, off-system copies and responsible contacts. No numerical SLA is implied. Maintain compatible database backups, release artifacts, necessary configuration and customer-managed content. Protect secrets and signing material in a separately authorized recovery process.</p><h2 id="before-changes" tabindex="-1">Before changes <a class="header-anchor" href="#before-changes" aria-label="Permalink to &quot;Before changes&quot;">​</a></h2><ol><li>Confirm target environment, installed release, database schema and candidate migration requirements.</li><li>Verify backup identity, checksum and readability. A readable archive is not proof of restoration; perform and record isolated restore tests.</li><li>Preserve customer content, domains, local themes, integration configuration and tenant access; define explicit rollback/forward-recovery criteria.</li><li>Obtain authorization and document the maintenance window. Use the approved update procedure only.</li></ol><h2 id="during-an-interruption" tabindex="-1">During an interruption <a class="header-anchor" href="#during-an-interruption" aria-label="Permalink to &quot;During an interruption&quot;">​</a></h2><p>Stop ambiguous retries. Preserve reservation references, payment identifiers and incident times without exposing credentials. Use the agreed manual dispatch fallback with restricted access and minimum necessary data. Verify actual payment and booking state before resubmission; never invent a provider result. Coordinate with support and record offline actions for reconciliation.</p><h2 id="restore-and-resume" tabindex="-1">Restore and resume <a class="header-anchor" href="#restore-and-resume" aria-label="Permalink to &quot;Restore and resume&quot;">​</a></h2><p>Only authorized technical staff may restore an affected environment. Test recovery in isolation first, verify schema and release compatibility, company boundaries, accounts, booking/dispatch state, financial ledger and retained content. Check enabled providers separately. Do not blindly roll back database migrations. Reconcile missed or duplicated operations, record recovery evidence and obtain approval before returning to service.</p><p>See <a href="/installation/">Installation</a>, <a href="/plus/software-update-manager.html">Software updates</a>, <a href="/tutorials/payment-review.html">Payment review</a> and <a href="/security-privacy/">Security &amp; Privacy</a>.</p>',11)])])}const h=a(n,[["render",o]]);export{m as __pageData,h as default};
